//! English entity names and vendor flags (`content/entity-info.tsv`), plus
//! per-placement name overrides (`content/object-names.tsv`). Both are
//! generated by `tools/import_entity_info.py` from portal.dat and
//! local_English.dat; they are presentation data, not gameplay rules.
use std::{collections::BTreeMap, sync::OnceLock};

pub struct Info {
    pub vendor: bool,
    pub name: Option<String>,
}

fn table() -> &'static BTreeMap<u32, Info> {
    static TABLE: OnceLock<BTreeMap<u32, Info>> = OnceLock::new();
    TABLE.get_or_init(|| {
        include_str!("../content/entity-info.tsv")
            .lines()
            .filter(|line| !line.is_empty() && !line.starts_with('#') && !line.starts_with("pyrealium-"))
            .filter_map(|line| {
                let mut fields = line.splitn(3, '\t');
                let entity = u32::from_str_radix(fields.next()?, 16).ok()?;
                let vendor = fields.next()? == "1";
                let name = fields.next().filter(|name| *name != "-").map(str::to_owned);
                Some((entity, Info { vendor, name }))
            })
            .collect()
    })
}

pub fn get(entity: u32) -> Option<&'static Info> {
    table().get(&entity)
}
pub fn is_vendor(entity: u32) -> bool {
    entity == crate::merchants::MERCHANT_ENTITY || get(entity).is_some_and(|info| info.vendor)
}
pub fn name(entity: u32) -> Option<&'static str> {
    get(entity).and_then(|info| info.name.as_deref())
}

/// Captured physics mode by object ID (`content/object-modes.tsv`).
/// Spawn packing does not apply these; later-client modes on static visuals
/// fault PhysicsObjRep. Actor visuals get standing from their DAT tables.
pub fn object_modes() -> impl Iterator<Item = (u64, u32)> {
    include_str!("../content/object-modes.tsv")
        .lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#') && !line.starts_with("pyrealium-"))
        .filter_map(|line| {
            let (id, mode) = line.split_once('\t')?;
            Some((u64::from_str_radix(id, 16).ok()?, u32::from_str_radix(mode, 16).ok()?))
        })
        // Death/corpse mode is never a spawn state.
        .filter(|&(_, mode)| mode != 0x41000003)
}

/// Placement name overrides by object ID.
pub fn object_names() -> impl Iterator<Item = (u64, &'static str)> {
    include_str!("../content/object-names.tsv")
        .lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#') && !line.starts_with("pyrealium-"))
        .filter_map(|line| {
            let (id, name) = line.split_once('\t')?;
            Some((u64::from_str_radix(id, 16).ok()?, name))
        })
}
